INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q1154466', '12 Warlords Rebellion', 'The Anarchy of the 12 Warlords (Vietnamese: Loạn 12 sứ quân, chữ Nôm: 亂𨑮𠄩使君; Sino-Vietnamese: Thập nhị sứ quân chi loạn, chữ Hán: 十二使君之亂), also the Period of the 12 Warlords, was a period of chaos and civil war in the history of Vietnam, from 965 to 968 caused by the succession of the Ngô dynasty after the death of King Ngô Quyền. This period is also sometimes simply called the Twelve Warlords (Vietnamese: Mười hai sứ quân, 𨑮𠄩使君).', 965, NULL, NULL, 968, NULL, NULL, 'year', '965–968', 50, 'https://en.wikipedia.org/wiki/Anarchy_of_the_12_Warlords'),
  ('Q7849268', 'Trịnh–Nguyễn War', 'The Trịnh–Nguyễn War (Vietnamese: Trịnh–Nguyễn phân tranh; chữ Hán: 鄭阮紛爭, lit. Trịnh–Nguyễn contention) was a prolonged civil war and conflict during the 17th–18th centuries waged between the two ruling families in Vietnam, the Trịnh lords of Đàng Ngoài and the Nguyễn lords of Đàng Trong, centered in today''s Central Vietnam.', 1627, NULL, NULL, NULL, NULL, NULL, 'year', '1627', 43, 'https://en.wikipedia.org/wiki/Tr%E1%BB%8Bnh%E2%80%93Nguy%E1%BB%85n_War'),
  ('Q3539853', 'Battle of Ngọc Hồi–Đống Đa', 'The Battle of Ngọc Hồi-Đống Đa or Qing invasion of Đại Việt (Vietnamese: Trận Ngọc Hồi - Đống Đa; Chinese: 清軍入越戰爭), also known as Victory of Kỷ Dậu (Vietnamese: Chiến thắng Kỷ Dậu), was fought between the forces of the Vietnamese Tây Sơn dynasty and the Chinese Qing dynasty in Ngọc Hồi (a place near Thanh Trì) and Đống Đa in northern Vietnam from 1788 to 1789. It resulted in the failure of the Chinese to restore the last Lê emperor Chiêu Thống, who had been usurped by the Tây Sơn.', 1788, NULL, NULL, NULL, NULL, NULL, 'year', '1788', 39, 'https://en.wikipedia.org/wiki/Battle_of_Ng%E1%BB%8Dc_H%E1%BB%93i-%C4%90%E1%BB%91ng_%C4%90a'),
  ('Q5361929', 'Siege of Tourane', 'The siege of Tourane (September 1858–March 1860) was a Vietnamese victory during the Cochinchina campaign, a punitive campaign against the Vietnamese launched by France and Spain in 1858. A joint Franco-Spanish expedition under the command of Admiral Charles Rigault de Genouilly captured Tourane (modern Da Nang) in September 1858, but was then besieged in the city by the Vietnamese and forced eventually to evacuate it in March 1860.', 1858, 9, 1, 1860, 3, 22, 'day', '1 September 1858 – 22 March 1860', 39, 'https://en.wikipedia.org/wiki/Siege_of_Tourane'),
  ('Q1998999', 'Siege of Saigon', 'The siege of Saigon, a two-year siege of the city by the Vietnamese after its capture on 17 February 1859 by a Franco-Spanish flotilla under the command of the French admiral Charles Rigault de Genouilly, was one of the major events of the Cochinchina campaign (1858–1862). Saigon was of great strategic importance, both as the key food-producing area of Vietnam and as the gateway to Cochinchina.', 1860, 3, NULL, 1861, 2, NULL, 'month', 'March 1860 – February 1861', 45, 'https://en.wikipedia.org/wiki/Siege_of_Saigon'),
  ('Q4870828', 'Battle of Cầu Giấy', 'The Battle of Cầu Giấy or Paper Bridge, fought on 19 May 1883, was one of the numerous clashes during the Tonkin Campaign (1883–86) between the French and the Black Flags. A small French force under the command of capitaine de vaisseau Henri Rivière attacked a strong Black Flag defensive position near the village of Cầu Giấy a few miles to the west of Hanoi, known to the French as Paper Bridge (Pont de Papier).', 1883, 5, 19, NULL, NULL, NULL, 'day', '19 May 1883', 39, 'https://en.wikipedia.org/wiki/Battle_of_C%E1%BA%A7u_Gi%E1%BA%A5y_(1883)'),
  ('Q3486048', 'Siege of Tuyên Quang', 'The siege of Tuyên Quang was an important confrontation between the French and the Chinese armies in Tonkin (northern Vietnam) during the Sino-French War (August 1884 – April 1885). A French garrison of 619 men, including two companies of the French Foreign Legion, successfully defended the French post of Tuyên Quang against vastly outnumbering Chinese forces in a four-month siege from 24 November 1884 to 3 March 1885.', 1884, 11, 24, 1885, 3, 3, 'day', '24 November 1884 – 3 March 1885', 39, 'https://en.wikipedia.org/wiki/Siege_of_Tuy%C3%AAn_Quang'),
  ('Q4870894', 'Battle of Dong Dang', 'The Battle of Đồng Đăng (23 February 1885) was an important French victory during the Sino-French War. The battle formed part of the French advance following the Lạng Sơn campaign and resulted in the temporary expulsion of Chinese forces from the Tonkin border region.', 1885, 2, 23, NULL, NULL, NULL, 'day', '23 February 1885', 39, 'https://en.wikipedia.org/wiki/Battle_of_%C4%90%E1%BB%93ng_%C4%90%C4%83ng_(1885)'),
  ('Q769960', 'August Revolution', 'The August Revolution (Vietnamese: Cách mạng tháng Tám), at the time known as the General Uprising (Vietnamese: Tổng khởi nghĩa cướp chính quyền, lit. ''Total uprising to seize power''), was a revolution led by the Viet Minh against the Japanese occupation of Vietnam and the Empire of Vietnam from 16 to 30 August 1945. The Empire of Vietnam was led by the Nguyễn dynasty and was backed by Japan.', 1945, 8, 16, 1945, 8, 30, 'day', '16 August 1945 – 30 August 1945', 64, 'https://en.wikipedia.org/wiki/August_Revolution'),
  ('Q962370', 'Battle of Hanoi', 'On December 19, 1946, Viet Minh soldiers detonated explosives in Hanoi, and the ensuing battle, known as the Battle of Hanoi marked the opening salvo of the First Indochina War.', 1946, 12, 19, 1947, 2, 18, 'day', '19 December 1946 – 18 February 1947', 48, 'https://en.wikipedia.org/wiki/Battle_of_Hanoi_(1946)'),
  ('Q2670487', 'My Trach Massacre', 'The Mỹ Trạch Massacre (Vietnamese: Thảm sát Mỹ Trạch) was a mass murder and wartime rape committed by the French Army against Vietnamese civilians in the First Indochina War. French soldiers committed the massacre in Mỹ Trạch village, Mỹ Thủy commune, Lệ Thủy District, Quảng Bình Province, Vietnam from 5 am to 8 am on 29 November 1948.', 1947, 11, 29, NULL, NULL, NULL, 'day', '29 November 1947', 47, 'https://en.wikipedia.org/wiki/M%E1%BB%B9_Tr%E1%BA%A1ch_massacre'),
  ('Q2748355', 'Battle of Route Coloniale 4', 'The Battle of Route Coloniale 4, also called the Autumn-Winter Border Campaign (Chiến Dịch Biên Giới Thu Đông) by the Viet Minh, was a battle of the First Indochina War. It took place along Route Coloniale 4 (RC4, also known as Highway 4), a road used to supply the French military base at Cao Bằng.', 1950, 10, 18, 1950, 10, 13, 'day', '18 October 1950 – 13 October 1950', 48, 'https://en.wikipedia.org/wiki/Battle_of_Route_Coloniale_4'),
  ('Q4871237', 'Battle of Hoa Binh', 'The Battle of Hòa Bình was fought during the First Indochina War. It occurred from 10 November 1951 to 25 February 1952, when French Union forces attempted to lure the Việt Minh out into the open and to force it to fight on French terms.', 1951, 11, 10, 1952, 2, 25, 'day', '10 November 1951 – 25 February 1952', 41, 'https://en.wikipedia.org/wiki/Battle_of_H%C3%B2a_B%C3%ACnh'),
  ('Q4872690', 'Battle of Vinh Yen', 'The Battle of Vĩnh Yên (Vietnamese: Trận Vĩnh Yên) which occurred from 13 to 17 January 1951, was a major engagement in the First Indochina War between the French Union and the communist Việt Minh. The French Union forces, including the French Armed Forces and Vietnamese National Army, led by World War II hero Jean de Lattre de Tassigny, inflicted a decisive defeat on the Việt Minh forces, which were commanded by Võ Nguyên Giáp.', 1951, NULL, NULL, 1951, 1, 17, 'year', '1951', 41, 'https://en.wikipedia.org/wiki/Battle_of_V%C4%A9nh_Y%C3%AAn'),
  ('Q2889446', 'Battle of Na San', 'The Battle of Nà Sản was fought between the French Union and the Việt Minh at Nà Sản, Sơn La Province, during the First Indochina War for control of the T’ai region in Northwest Vietnam. The battle ended with the victory of the French Union (France and State of Vietnam).', 1952, 11, 23, 1952, 12, 2, 'day', '23 November 1952 – 2 December 1952', 43, 'https://en.wikipedia.org/wiki/Battle_of_N%C3%A0_S%E1%BA%A3n'),
  ('Q604897', 'Battle of Dien Bien Phu', 'The Battle of Điện Biên Phủ was a defeat of the French Union forces by the Viet Minh forces in the First Indochina War. It took place between 13 March and 7 May 1954.', 1954, 3, 13, 1954, 5, 7, 'day', '13 March 1954 – 7 May 1954', 77, 'https://en.wikipedia.org/wiki/Battle_of_Dien_Bien_Phu'),
  ('Q4871659', 'Battle of Mang Yang Pass', 'The Battle of Mang Yang Pass (also known as the Battle of An Khê or the Battle of Đắk Pơ) was one of the last battles of the First Indochina War between the French Union and Việt Minh which took place from 24 to 29 June 1954. The battle was one of the bloodiest defeats of the French Union forces, along with the battle of Dien Bien Phu shortly beforehand.', 1954, NULL, NULL, 1954, 7, 17, 'year', '1954', 41, 'https://en.wikipedia.org/wiki/Battle_of_Mang_Yang_Pass'),
  ('Q3380491', 'Battle of Saigon', 'The Battle of Saigon was a week-long battle in South Vietnam (State of Vietnam) between the army of Diệm''s government and the private army of the Bình Xuyên organised crime syndicate. At the time, the Bình Xuyên was licensed with controlling the national police by the Chief of State Bảo Đại, and Prime Minister Ngô Đình Diệm issued an ultimatum for them to surrender and come under state control.', 1955, 4, 28, 1955, 5, NULL, 'day', '28 April 1955 – May 1955', 43, 'https://en.wikipedia.org/wiki/Battle_of_Saigon_(1955)'),
  ('Q4871119', 'Battle of Go Cong', 'The Battle of Gò Công was a small battle during the Vietnam War. It took place on 3 September 1963 near Gò Công, Định Tường Province, after the General Staff of the Viet Cong (VC) (controlled by North Vietnam) called for "another Ấp Bắc" on South Vietnamese forces.', 1963, 9, 3, NULL, NULL, NULL, 'day', '3 September 1963', 39, 'https://en.wikipedia.org/wiki/Battle_of_G%C3%B2_C%C3%B4ng'),
  ('Q550500', 'Battle of Nam Dong', 'The battle of Nam Đông took place from July 5–6, 1964 during the Vietnam War, when the Viet Cong (VC) and People''s Army of Vietnam (PAVN) attacked the Nam Đông CIDG camp in an attempt to overrun it. During the battle, 57 South Vietnamese defenders, two Americans, an Australian military advisor, and at least 62 attackers were killed.', 1964, NULL, NULL, 1964, 7, 6, 'year', '1964', 41, 'https://en.wikipedia.org/wiki/Battle_of_Nam_Dong'),
  ('Q1320031', 'Battle of Binh Gia', 'The Battle of Bình Giã (Vietnamese: Trận Bình Giã) was conducted by the Viet Cong (VC) and People''s Army of Vietnam (PAVN) from 28 December 1964, to 1 January 1965, during the Vietnam War in Bình Giã, Phước Tuy province (now part of Bà Rịa–Vũng Tàu province), South Vietnam. 1964 marked a decisive turning point in the Vietnam War.', 1964, 12, 28, 1965, 1, 1, 'day', '28 December 1964 – 1 January 1965', 41, 'https://en.wikipedia.org/wiki/Battle_of_Binh_Gia'),
  ('Q3381201', 'Battle of An Lao', 'The Battle of An Lão took place during the Vietnam War in the An Lão District of Bình Định Province between 7 and 9 December 1964. The battle was part of a larger operation by the communist 5th Military Region known as Campaign An Lão to capture An Lão valley, and use it as a corridor between their military bases in Quảng Ngãi Province and Bình Định Province.', 1964, NULL, NULL, 1964, 12, 9, 'year', '1964', 37, 'https://en.wikipedia.org/wiki/Battle_of_An_L%C3%A3o'),
  ('Q588774', 'Battle of Dong Xoai', 'The Battle of Đồng Xoài (Vietnamese: Trận Đồng Xoài) was a major battle fought during the Vietnam War as part of the Viet Cong (VC) Summer Offensive of 1965. It took place in Phước Long Province, South Vietnam, between 9 and 13 June 1965.', 1965, NULL, NULL, 1965, 6, 13, 'year', '1965', 43, 'https://en.wikipedia.org/wiki/Battle_of_%C4%90%E1%BB%93ng_Xo%C3%A0i'),
  ('Q714749', 'Battle of Ia Drang', 'The Battle of Ia Drang (Vietnamese: Trận Ia Đrăng, [iə̯ ɗrăŋ]; in English ) was the first major battle between the United States Army and the People''s Army of Vietnam (PAVN), as part of the Pleiku campaign conducted early in the Vietnam War, at the eastern foot of the Chu Pong Massif in the central highlands of Vietnam, in 1965. It is notable for being the first large scale helicopter air assault and also the first use of Boeing B-52 Stratofortress strategic bombers in a tactical support role.', 1965, 11, 14, 1965, 11, 18, 'day', '14 November 1965 – 18 November 1965', 64, 'https://en.wikipedia.org/wiki/Battle_of_Ia_Drang'),
  ('Q259526', 'Battle of Long Tan', 'The Battle of Long Tan (18–21 August 1966) took place in a rubber plantation near Long Tân, in Phước Tuy Province, South Vietnam, during the Vietnam War. The action was fought between Viet Cong (VC) and People''s Army of Vietnam (PAVN) units on one side and elements of the 1st Australian Task Force (1 ATF) on the other.', 1966, 8, 18, NULL, NULL, NULL, 'day', '18 August 1966', 53, 'https://en.wikipedia.org/wiki/Battle_of_Long_Tan'),
  ('Q497528', 'Binh Hoa massacre', 'The Bình Hòa Massacre, (Vietnamese: thảm sát Bình Hoà, Korean: 빈호아 학살) was a massacre purportedly conducted by South Korean forces between December 3 and December 6, 1966, of 430 unarmed civilians in Bình Hòa village, Quảng Ngãi Province in South Vietnam. In 2000, however, it was reported that a monument within the village, gave the dates of the massacre as October 22, 24, and 26, 1966 and said that 403 people were killed by the South Koreans.', 1966, 12, NULL, 1966, 12, 6, 'month', 'December 1966 – 6 December 1966', 47, 'https://en.wikipedia.org/wiki/B%C3%ACnh_H%C3%B2a_massacre'),
  ('Q682195', 'Operation Masher', 'Operation Masher, also known as Operation White Wing, (24 January—6 March 1966) was the largest search and destroy mission that had been carried out in the Vietnam War up until that time. It was a combined mission of the United States Army, Army of the Republic of Vietnam (ARVN), and Republic of Korea Army (ROK) in Bình Định Province on the central coast of South Vietnam.', 1966, 1, 24, 1966, 3, 6, 'day', '24 January 1966 – 6 March 1966', 39, 'https://en.wikipedia.org/wiki/Operation_Masher'),
  ('Q1519185', 'Operation Hastings', 'Operation Hastings was an American military operation in the Vietnam War. The operation was a qualified success in that it pushed the People''s Army of Vietnam (PAVN) forces back across the Demilitarized Zone (DMZ).', 1966, 7, 15, 1966, 8, 3, 'day', '15 July 1966 – 3 August 1966', 41, 'https://en.wikipedia.org/wiki/Operation_Hastings'),
  ('Q2026028', 'Operation Crimp', 'Operation Crimp (8–14 January 1966), also known as the Battle of the Ho Bo Woods, was a joint US-Australian military operation during the Vietnam War, which took place 20 kilometres (12 mi) north of Cu Chi in Binh Duong Province, South Vietnam. The operation targeted a key Viet Cong headquarters that was believed to be concealed underground, and involved two brigades under the command of the US 1st Infantry Division, including the 1st Battalion, Royal Australian Regiment (1 RAR) which was attached to the US 173rd Airborne Brigade.', 1966, 1, 14, NULL, NULL, NULL, 'day', '14 January 1966', 39, 'https://en.wikipedia.org/wiki/Operation_Crimp'),
  ('Q4984261', 'Buddhist Uprising', 'The Buddhist Uprising of 1966 (Vietnamese: Nổi dậy Phật giáo 1966), or more widely known in Vietnam as the Crisis in Central Vietnam (Biến động Miền Trung), was a period of civil and military unrest in South Vietnam, mostly in the I Corps area in the north of the country in central Vietnam. The area is a center of Vietnamese Buddhism, and at the time, activist Buddhist monks and civilians were at the forefront of opposition to a series of military juntas that had been ruling the nation, as well as prominently questioning the escalation of the Vietnam War.', 1966, 6, 8, 1966, 6, 8, 'day', '8 June 1966', 41, 'https://en.wikipedia.org/wiki/Buddhist_Uprising'),
  ('Q220882', 'Operation Junction City', 'Operation Junction City was an 82-day military operation conducted by United States (US) and South Vietnam forces against Viet Cong (VC) forces begun on 22 February 1967 during the Vietnam War. It was the first US combat airborne operation since the Korean War and one of the largest airmobile operations of the war.', 1967, 2, 22, 1967, 5, 14, 'day', '22 February 1967 – 14 May 1967', 51, 'https://en.wikipedia.org/wiki/Operation_Junction_City'),
  ('Q487431', 'Battle of Tra Binh Dong', 'The Battle of Trà Bình (Vietnamese: Trận Quang Thạnh; Korean: 짜빈동 전투) was fought in the Trà Bình village, Trà Bồng District, on February 14–15, 1967 during the Vietnam War. The 11th Company, 3rd Battalion, 2nd Marine Brigade defeated a regimental-sized attack in four hours of close quarters combat.', 1967, NULL, NULL, 1967, 2, 15, 'year', '1967', 37, 'https://en.wikipedia.org/wiki/Battle_of_Tr%C3%A0_B%C3%ACnh'),
  ('Q709365', 'Dak Son Massacre', 'The Đắk Sơn Massacre was the massacre of Montagnard villagers perpetrated by the Viet Cong on 5 December 1967 during the Vietnam War, in the village of Đắk Sơn, Phước Long province, South Vietnam.', 1967, 12, 5, NULL, NULL, NULL, 'day', '5 December 1967', 51, 'https://en.wikipedia.org/wiki/%C4%90%E1%BA%AFk_S%C6%A1n_massacre'),
  ('Q859217', 'Operation Cedar Falls', 'Operation Cedar Falls was a military operation of the Vietnam War conducted primarily by US forces that took place from 8 to 26 January 1967. The aim of the massive search-and-destroy operation was to eradicate the Iron Triangle, an area northwest of Saigon that had become a major stronghold of the Viet Cong (VC).', 1967, 1, 8, 1967, 1, 26, 'day', '8 January 1967 – 26 January 1967', 48, 'https://en.wikipedia.org/wiki/Operation_Cedar_Falls'),
  ('Q901263', 'Battle of Dak To', 'The Battle of Dak To (Vietnamese: Chiến dịch Đắk Tô - Tân Cảnh) in Vietnam was a series of major engagements of the Vietnam War that took place between 3 and 23 November 1967, in Kontum Province, in the Central Highlands of the Republic of Vietnam (South Vietnam). The action at Đắk Tô was one of a series of People''s Army of Vietnam (PAVN) offensive initiatives that began during the second half of the year.', 1967, 11, 3, 1967, 11, 23, 'day', '3 November 1967 – 23 November 1967', 51, 'https://en.wikipedia.org/wiki/Battle_of_Dak_To'),
  ('Q1230358', 'Battle of Hill 881', 'The Hill Fights (also known as the First Battle of Khe Sanh) took place during the Vietnam War between the People''s Army of Vietnam (PAVN) 325C Division and United States Marines on several hill masses north of the Khe Sanh Combat Base in northwest Quảng Trị Province.', 1967, 4, 24, 1967, 5, 11, 'day', '24 April 1967 – 11 May 1967', 43, 'https://en.wikipedia.org/wiki/The_Hill_Fights'),
  ('Q1374042', '1967 USS Forrestal fire', 'On 29 July 1967, a fire broke out on board the aircraft carrier USS Forrestal, which was engaged in combat in the Gulf of Tonkin during the Vietnam War. The fire was caused by an inadvertently fired Zuni rocket which ruptured an external fuel tank of an A-4 Skyhawk.', 1967, 7, 29, NULL, NULL, NULL, 'day', '29 July 1967', 48, 'https://en.wikipedia.org/wiki/1967_USS_Forrestal_fire'),
  ('Q82542', 'Tet Offensive', 'The Tet Offensive was both a major escalation and one of the largest military campaigns of the Vietnam War. The North Vietnamese People''s Army of Vietnam (PAVN) and the Viet Cong (VC) launched a surprise attack on 30 and 31 January 1968 against the forces of the South Vietnamese Army of the Republic of Vietnam (ARVN), the United States Armed Forces and their allies, targeting military and civilian command and control centers throughout South Vietnam.', 1968, 1, 30, 1968, 9, 23, 'day', '30 January 1968 – 23 September 1968', 72, 'https://en.wikipedia.org/wiki/Tet_Offensive'),
  ('Q486226', 'Phong Nhi and Phong Nhat massacre', 'The Phong Nhị and Phong Nhất massacre (Korean: 퐁니·퐁넛 양민학살 사건, Vietnamese: Thảm sát Phong Nhất và Phong Nhị) was a massacre of unarmed civilians in the villages of Phong Nhị and Phong Nhất, Điện Bàn District of Quảng Nam Province in South Vietnam reported to have been conducted by the 2nd Marine Brigade of the Republic of Korea Marines (ROKMC) during the Vietnam War on 12 February 1968.', 1968, 2, 12, NULL, NULL, NULL, 'day', '12 February 1968', 41, 'https://en.wikipedia.org/wiki/Phong_Nh%E1%BB%8B_and_Phong_Nh%E1%BA%A5t_massacre'),
  ('Q697053', 'Battle of Hue', 'The Battle of Huế (31 January 1968 – 2 March 1968) was a major battle in the Tết Offensive launched by North Vietnam and the Việt Cộng during the Vietnam War. Initially losing control of most of Huế and its surroundings, the combined forces of South Vietnam and the United States gradually recaptured the city after a little over one month of intense fighting.', 1968, 3, 2, 1968, 3, 3, 'day', '2 March 1968 – 3 March 1968', 61, 'https://en.wikipedia.org/wiki/Battle_of_Hu%E1%BA%BF'),
  ('Q2889954', 'Battle of Saigon', 'The First Battle of Saigon, fought during the Tet Offensive of the Vietnam War, was the coordinated attack by communist forces, including both the North Vietnamese Army and the Viet Cong (VC), against Saigon, the capital of South Vietnam.', 1968, NULL, NULL, 1968, 3, 7, 'year', '1968', 43, 'https://en.wikipedia.org/wiki/Battle_of_Saigon_(1968)'),
  ('Q247395', 'Battle of Hamburger Hill', 'The Battle of Hamburger Hill (13–20 May 1969) was fought by United States Army (US Army) and Army of the Republic of Vietnam (ARVN) forces against People''s Army of Vietnam (PAVN) forces during Operation Apache Snow of the Vietnam War. Though the heavily fortified Hill 937, a ridge of the mountain Dong Ap Bia in central Vietnam near its western border with Laos, had little strategic value, US command ordered its capture by a frontal assault, only to abandon it soon thereafter.', 1969, 5, 10, 1969, 5, 20, 'day', '10 May 1969 – 20 May 1969', 61, 'https://en.wikipedia.org/wiki/Battle_of_Hamburger_Hill'),
  ('Q692885', 'Operation Ivory Coast', 'Operation Ivory Coast was a mission conducted by United States Special Operations Forces and other American military elements to rescue U.S. prisoners of war during the Vietnam War. It was also the first joint military operation in United States history conducted under the direct control of the Chairman of the Joint Chiefs of Staff.', 1970, 11, 21, NULL, NULL, NULL, 'day', '21 November 1970', 51, 'https://en.wikipedia.org/wiki/Operation_Ivory_Coast'),
  ('Q486866', 'Operation Linebacker II', 'Operation Linebacker II, sometimes referred to as the Christmas bombing and, in Vietnam, the Twelve days and nights, or Điện Biên Phủ of the Sky, was a strategic bombing campaign conducted by the United States against military and industrial areas of North Vietnam from 18 December to 29 December 1972, during the Vietnam War. More than 20,000 tons of ordnance was dropped, primarily targeting Hanoi and Haiphong, and at least 1,624 civilians were killed.', 1972, 12, 18, 1972, 12, 29, 'day', '18 December 1972 – 29 December 1972', 59, 'https://en.wikipedia.org/wiki/Operation_Linebacker_II'),
  ('Q2237223', 'First Battle of Quảng Trị', 'The First Battle of Quảng Trị (Vietnamese: Chiến dịch Trị Thiên) resulted in the first major victory for the People''s Army of Vietnam (PAVN) during the Easter Offensive of 1972. Quảng Trị Province was a major battleground for the opposing forces during the Vietnam War.', 1972, 3, 30, 1972, 5, 1, 'day', '30 March 1972 – 1 May 1972', 37, 'https://en.wikipedia.org/wiki/First_Battle_of_Qu%E1%BA%A3ng_Tr%E1%BB%8B'),
  ('Q4273438', 'Battle of Kontum', 'The lead-up to the Battle of Kontum began in mid-1971, when North Vietnam decided that their performance in Operation Lam Son 719 indicated that the time had come for large-scale conventional offensives that could end the war quickly. The resulting offensive, planned for the spring of 1972, would be known as the Easter Offensive in Western media, the 1972 Spring–Summer Offensive (Chiến dịch Xuân–Hè 1972) in North Vietnam, or the Fiery Red Summer (Mùa hè đỏ lửa) in South Vietnam.', 1972, 6, 9, 1972, 5, 27, 'day', '9 June 1972 – 27 May 1972', 41, 'https://en.wikipedia.org/wiki/Battle_of_Kontum'),
  ('Q8740', 'Vietnam War', 'The Vietnam War (c. 1955 – 30 April 1975) was an armed conflict in Vietnam, Laos, and Cambodia fought between North Vietnam (Democratic Republic of Vietnam) and South Vietnam (Republic of Vietnam) and their allies. North Vietnam was supported by the Soviet Union and China, while South Vietnam was supported by the United States and other anti-communist nations.', 1975, 4, 30, 1975, 4, 30, 'day', '30 April 1975', 97, 'https://en.wikipedia.org/wiki/Vietnam_War'),
  ('Q249853', 'Insurgency in Laos', 'The insurgency in Laos is a low-intensity conflict between the Lao People''s Democratic Republic on one side and former members of the Secret Army, Laotian royalists, Hmong fighters, and other highland Laotian ethnic minorities on the other. These groups have faced reprisals from the Lao People''s Army and Vietnam People''s Army for their support of the United States-aligned, anti-communist military campaigns in Laos during the Laotian Civil War, which the insurgency is an extension of itself.', 1975, 12, 2, NULL, NULL, NULL, 'day', '2 December 1975', 51, 'https://en.wikipedia.org/wiki/Insurgency_in_Laos'),
  ('Q482456', 'Fall of Saigon', 'Saigon, the capital of South Vietnam, was captured by North Vietnam on 30 April 1975. This caused the evacuation of thousands of civilians and U.S. personnel, and ended the Vietnam War.', 1975, 4, 30, NULL, NULL, NULL, 'day', '30 April 1975', 70, 'https://en.wikipedia.org/wiki/Fall_of_Saigon'),
  ('Q487076', 'Battle of Xuan Loc', 'The Battle of Xuân Lộc (Vietnamese: Trận Xuân Lộc) was the last major battle of the Vietnam War that took place at Xuân Lộc, Biên Hòa Province (today Đồng Nai Province). Over a period of 12 days between 9 and 21 April 1975, the outnumbered South Vietnamese attempted to stop the North Vietnamese forces from overrunning the town and breaking through towards South Vietnam''s capital, Saigon.', 1975, 4, 9, 1975, 4, 21, 'day', '9 April 1975 – 21 April 1975', 48, 'https://en.wikipedia.org/wiki/Battle_of_Xu%C3%A2n_L%E1%BB%99c'),
  ('Q796498', 'Third Indochina War', 'The Third Indochina War was a series of interconnected military conflicts among the various communist factions over strategic influence in mainland Southeast Asia after communist victory in South Vietnam, Laos, and Cambodia in 1975. The conflict primarily started due to continued raids and incursions by the Khmer Rouge into Vietnamese territory that they sought to retake.', 1975, 5, 1, 1991, 10, 23, 'day', '1 May 1975 – 23 October 1991', 53, 'https://en.wikipedia.org/wiki/Third_Indochina_War'),
  ('Q796398', 'Ba Chúc massacre', 'The Ba Chúc massacre (Vietnamese: Thảm sát Ba Chúc) was the mass killing of 3,157 civilians in Ba Chúc, An Giang province, Vietnam, by the Kampuchea Revolutionary Army (Khmer Rouge) from 18 to 30 April 1978. It was a spillover of the Cambodian genocide which also targeted Vietnamese people mainly in Cambodia.', 1978, 4, 18, 1978, 4, 30, 'day', '18 April 1978 – 30 April 1978', 52, 'https://en.wikipedia.org/wiki/Ba_Ch%C3%BAc_massacre'),
  ('Q342587', 'Đổi Mới', 'Đổi Mới (IPA: [ɗo᷉i mɤ̂ːi]; transl. "renovation" or "innovation") is the name given to the economic reforms process of Vietnam since late 1986 with the goal of creating a "socialist-oriented market economy". The term đổi mới itself is a general term with wide use in the Vietnamese language meaning "innovate" or "renovate".', 1986, NULL, NULL, NULL, NULL, NULL, 'year', '1986', 61, 'https://en.wikipedia.org/wiki/%C4%90%E1%BB%95i_M%E1%BB%9Bi'),
  ('Q175767', 'Johnson South Reef skirmish', 'The Johnson South Reef skirmish took place on 14 March 1988 between military forces of China and Vietnam, on the Johnson South Reef in the Union Banks region of the Spratly Islands, in the South China Sea.', 1988, 3, 14, NULL, NULL, NULL, 'day', '14 March 1988', 47, 'https://en.wikipedia.org/wiki/Johnson_South_Reef_skirmish'),
  ('Q635533', 'Cambodian–Vietnamese War', 'The Cambodian–Vietnamese War was an armed conflict from 1978 to 1989 between Democratic Kampuchea and the Socialist Republic of Vietnam, and their respective allies. It began in December 1978, with smaller clashes culminating into a Vietnamese invasion of Cambodia which toppled the Khmer Rouge regime and ended in 1989 with the withdrawal of Vietnamese forces from Cambodia.', 1989, 9, 26, 1991, 10, 23, 'day', '26 September 1989 – 23 October 1991', 73, 'https://en.wikipedia.org/wiki/Cambodian%E2%80%93Vietnamese_War'),
  ('Q18510562', 'Vietnam Airlines Flight 474', 'Vietnam Airlines Flight 474 was a scheduled passenger flight from Ho Chi Minh City-Tan Son Nhat International Airport, Vietnam to Nha Trang Airport, Vietnam Airport. During landing, the plane crashed on approach to Nha Trang Airport on 14 November 1992 during Cyclone Forrest.', 1992, 11, 14, NULL, NULL, NULL, 'day', '14 November 1992', 47, 'https://en.wikipedia.org/wiki/Vietnam_Airlines_Flight_474'),
  ('Q150495', '2011 Tarlay earthquake', 'The 2011 Shan earthquake occurred on 24 March in Shan State, Myanmar. The earthquake measured Mw 6.8 and had an epicenter northwest of the border between Myanmar, Thailand and Laos.', 2011, 3, 24, NULL, NULL, NULL, 'day', '24 March 2011', 61, 'https://en.wikipedia.org/wiki/2011_Shan_earthquake'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q100293305', '2020 Vietnamese floods', 'The 2020 Central Vietnam floods were a series of floods in Central Vietnam, which also affected some areas in Cambodia and Laos in October and early November 2020. The floods focused heavily in several provinces including Thừa Thiên Huế, Hà Tĩnh, Quảng Bình, Quảng Trị, and Quảng Ngãi.', 2020, NULL, NULL, NULL, NULL, NULL, 'year', '2020', 39, 'https://en.wikipedia.org/wiki/2020_Central_Vietnam_floods'),
  ('Q122452764', '2023 Hanoi building fire', 'On 12 September 2023, at around 23:30 ICT (UTC+07:00), a fire occurred in a nine-story microapartment building in the 29th alley of Khương Hạ street, Khương Đình ward, Thanh Xuân district, Hanoi, Vietnam. Of the approximately 150 people residing in the building, 56 were killed by the fire and 37 others were injured.', 2023, 9, 12, NULL, NULL, NULL, 'day', '12 September 2023', 50, 'https://en.wikipedia.org/wiki/2023_Hanoi_building_fire');
